def safe_save(b,figpatients=None,coverage=None):
 full=b.s['figures'];uncaptioned=[f for f in full if not f.get('caption_segment_ids')];b.s['figures']=[f for f in full if f.get('caption_segment_ids')]
 b.save(figpatients,coverage);b.s['figures']=full
 if uncaptioned:
  path=ROOT/'drafts'/f"{b.s['article_id']}.json";o=json.loads(path.read_text())
  for f in uncaptioned:o['figures'].append({'figure_id':f['figure_id'],'caption_evidence':[],'patient_ids':[],'scope':'unresolved','panels':[],'caption_summary':None,'visual_status':'not_inspected','visual_description':None,'attribution_notes':'Uncaptioned graphic; patient ownership and clinical content unresolved. Graphic reference: '+', '.join(f.get('graphic_references',[]))})
  o['article_limitations'].append('Source contains uncaptioned graphics, including an unwrapped graphic without figure ID; their clinical ownership remains unresolved.')
  path.write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n')
